  [436367] = { "Ottieni l'abilità Two-Handed Mastery:\n\n$I1\nOgni volta che colpisci un nemico con un'arma a due mani, ottieni il $N1% di velocità d'attacco con le armi a due mani, il $N2% di potenza d'attacco in più e il $N3% di probabilità in più di colpire con gli incantesimi per $D1. L'effetto si perde se colpisci un nemico con un'arma a una mano.", nil, 0x1f3e5823, nil, "um" },
